async function fixedCleanupFixture(stage:Stage='CLEANUP',confirmed=false){
  const f=await fixture(stage,false,confirmed,false,true),pinned:OwnedCleanupInput={profileDigest:digest(f.profile),sourceImageSha256:sha256(f.image),widthPx:4,heightPx:4};
  const lamaOptions:LocalLaMaOptions={enabled:true,identity:{codeCommit:lamaCodeCommit,weightsSha256:'a'.repeat(64),configSha256:'b'.repeat(64),weightsLicenseVerified:true,runtimeVerified:true},profile:f.profile,executor:{dispatch:f.executorDispatch,lookup:f.executorLookup},bounds:{maxCapturedExecutions:32,maxInFlightBytes:1024*1024},ownedCleanupInput:pinned};
  f.executorDispatch.mockImplementation(async({capture},onStarted)=>{f.events.push('lama:dispatch');await onStarted(f.start(capture));return f.lamaReply(capture,false);});f.executorLookup.mockImplementation(async capture=>f.lamaReply(capture,false));f.options.lama=new LocalLaMaAdapter(lamaOptions);f.options.ownedCleanupInput=pinned;return {...f,pinned,lamaOptions};
}
const fixedEntries=['VALIDATE','DISPATCH','LOOKUP','CHECKPOINT'] as const;
async function fixedEntry(f:Awaited<ReturnType<typeof fixedCleanupFixture>>,pipeline:OperationalPipelineProvider,entry:typeof fixedEntries[number],input=f.input,observation=f.providerObservation(input)){
  if(entry==='VALIDATE')return pipeline.validateInput(input,f.context);if(entry==='DISPATCH')return pipeline.dispatch(input,vi.fn(),f.context);if(entry==='LOOKUP')return pipeline.lookup(input.executionId,input,f.context);return pipeline.validateObservation(input,observation,f.context);
}

